PRAGMA foreign_keys = ON;
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, email_verified INTEGER NOT NULL, image TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, role TEXT NOT NULL DEFAULT 'viewer');
CREATE TABLE session (id TEXT PRIMARY KEY, expires_at INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, ip_address TEXT, user_agent TEXT, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE INDEX session_user ON session(user_id);
CREATE TABLE account (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, provider_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, access_token TEXT, refresh_token TEXT, id_token TEXT, access_token_expires_at INTEGER, refresh_token_expires_at INTEGER, scope TEXT, password TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE rate_limit (id TEXT PRIMARY KEY, key TEXT UNIQUE NOT NULL, count INTEGER NOT NULL, last_request INTEGER NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE households (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT, locale TEXT NOT NULL, code_hash TEXT NOT NULL UNIQUE, revision INTEGER NOT NULL DEFAULT 0, last_submission TEXT);
CREATE TABLE guests (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE, name TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('adult','child','infant')));
CREATE INDEX guests_household ON guests(household_id);
CREATE TABLE invitations (household_id TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE, event_id TEXT NOT NULL, PRIMARY KEY(household_id,event_id));
CREATE TABLE guest_sessions (token_hash TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE rsvps (guest_id TEXT NOT NULL REFERENCES guests(id) ON DELETE CASCADE, event_id TEXT NOT NULL, attending INTEGER NOT NULL CHECK(attending IN (0,1)), meal TEXT NOT NULL DEFAULT '', dietary TEXT NOT NULL DEFAULT '', accessibility TEXT NOT NULL DEFAULT '', transport TEXT NOT NULL DEFAULT '', PRIMARY KEY(guest_id,event_id));
CREATE TABLE submissions (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE, created_at INTEGER NOT NULL);
CREATE TABLE seating_tables (id TEXT PRIMARY KEY, event_id TEXT NOT NULL, name TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity > 0));
CREATE TABLE seats (guest_id TEXT NOT NULL REFERENCES guests(id) ON DELETE CASCADE, event_id TEXT NOT NULL, table_id TEXT NOT NULL REFERENCES seating_tables(id) ON DELETE CASCADE, PRIMARY KEY(guest_id,event_id));
CREATE TRIGGER seats_capacity BEFORE INSERT ON seats WHEN (SELECT COUNT(*) FROM seats WHERE table_id=NEW.table_id AND guest_id!=NEW.guest_id) >= (SELECT capacity FROM seating_tables WHERE id=NEW.table_id) BEGIN SELECT RAISE(ABORT,'tableFull'); END;
CREATE TRIGGER seats_valid BEFORE INSERT ON seats WHEN NOT EXISTS (SELECT 1 FROM seating_tables t JOIN rsvps r ON r.event_id=t.event_id WHERE t.id=NEW.table_id AND t.event_id=NEW.event_id AND r.guest_id=NEW.guest_id AND r.attending=1) BEGIN SELECT RAISE(ABORT,'seatRequiresAttendance'); END;
CREATE TABLE reservations (id TEXT PRIMARY KEY, item_id TEXT NOT NULL, household_id TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN ('reserved','purchased','cancelled')), expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX reservations_item ON reservations(item_id,status,expires_at);
CREATE TABLE media (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE, object_key TEXT NOT NULL UNIQUE, name TEXT NOT NULL, content_type TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes>0), caption TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('uploading','receiving','pending','approved','rejected')), created_at INTEGER NOT NULL);
CREATE INDEX media_status ON media(status,created_at);
CREATE TABLE outbox (id TEXT PRIMARY KEY, recipient TEXT NOT NULL, subject TEXT NOT NULL, html TEXT NOT NULL, plain_text TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt INTEGER NOT NULL, lease_until INTEGER NOT NULL DEFAULT 0, last_error TEXT, created_at INTEGER NOT NULL);
CREATE INDEX outbox_pending ON outbox(status,next_attempt);
CREATE TABLE limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE audit (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, created_at INTEGER NOT NULL);
